int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, r;
    while (cin >> n >> m >> r) {
        if (n == 0 && m == 0 && r == 0) break;

        vector<int> board(n + 2, 0); // 1-indexed, positions 1..n, extra for start/end
        // board[i] = movement offset when landing on position i
        // start = position 1, goal = position n (but we treat reaching n as success)
        for (int i = 1; i <= n; ++i) {
            string cmd;
            cin >> cmd;
            if (cmd[0] == '0') {
                board[i] = 0; // no command
            } else if (cmd[0] == '+') {
                board[i] = stoi(cmd.substr(1));
            } else if (cmd[0] == '-') {
                board[i] = -stoi(cmd.substr(1));
            }
        }

        vector<int> roulette(r);
        for (int i = 0; i < r; ++i) {
            cin >> roulette[i];
        }

        // BFS/DP: dp[pos] = true if reachable with some sequence of roulette outcomes
        // We only care about positions 1..n, but movements can go outside temporarily
        // Use BFS because roulette outcomes are given in order? No, we can choose any order?
        // Problem: we have a fixed sequence of roulette numbers? Or we can use them in any order?
        // The statement: "based on the rules of movements specified on the board and the outcomes of a roulette"
        // It says "the roulette generates numbers between 1 and a maximum value" but then input gives r numbers.
        // It seems we have a set of roulette outcomes, we can use each at most once, in any order.
        // We need to see if there exists a permutation of the roulette outcomes that leads to end.
        // This is a typical DP over subsets (r <= 10? not given). Let's check constraints? Not given.
        // But typical Japanese problems: r <= 10 or small. We'll do DP over subsets.
        // However, n can be up to maybe 100? We'll do DP[pos][mask] = reachable.
        // Since r might be up to maybe 12? We'll assume r <= 10 for subset DP.
        // Alternative: treat as graph with states (pos, used_mask). Use BFS.

        // Let's implement DP over subsets.
        int max_mask = 1 << r;
        vector<vector<bool>> dp(n + 2, vector<bool>(max_mask, false));
        dp[1][0] = true; // start at position 1 with no roulette used

        for (int mask = 0; mask < max_mask; ++mask) {
            for (int pos = 1; pos <= n; ++pos) {
                if (!dp[pos][mask]) continue;
                // try each unused roulette outcome
                for (int i = 0; i < r; ++i) {
                    if (mask & (1 << i)) continue;
                    int step = roulette[i];
                    int newPos = pos + step;
                    // clamp to valid range
                    if (newPos < 1) newPos = 1;
                    if (newPos > n) newPos = n;
                    // apply board command at newPos
                    int offset = board[newPos];
                    int finalPos = newPos + offset;
                    if (finalPos < 1) finalPos = 1;
                    if (finalPos > n) finalPos = n;
                    // if we reach n, success
                    if (finalPos == n) {
                        cout << "OK\n";
                        goto next_dataset;
                    }
                    dp[finalPos][mask | (1 << i)] = true;
                }
            }
        }

        // If we exhaust all states without reaching n
        cout << "NG\n";
        next_dataset:;
    }

    return 0;
}

