int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n, m;
        cin >> n >> m;
        if (!cin) return 0;
        if (n == 0 && m == 0) break;

        vector<int> a(n + 1, 0); // 0..n, where n is goal
        for (int i = 1; i <= n - 1; ++i) cin >> a[i];

        vector<vector<int>> rev(n + 1);

        for (int i = 0; i < n; ++i) {
            for (int r = 1; r <= m; ++r) {
                int j = min(i + r, n);        // roulette move
                int k = j + a[j];             // board instruction
                if (k < 0) k = 0;             // back past start
                if (k > n) k = n;             // forward past goal
                rev[k].push_back(i);          // i can reach k in one turn
            }
        }

        vector<int> vis(n + 1, 0);
        queue<int> q;
        vis[n] = 1;
        q.push(n);

        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int u : rev[v]) {
                if (!vis[u]) {
                    vis[u] = 1;
                    q.push(u);
                }
            }
        }

        cout << (vis[0] ? "OK" : "NG") << '\n';
    }

    return 0;
}

