#define MAX_N 105
#define MAX_M 1005

int main() {
    int n, m, k;
    while (scanf("%d %d %d", &n, &m, &k) == 3) {
        if (n == 0 && m == 0 && k == 0) break;

        int moves[MAX_N];
        for (int i = 1; i <= n; i++) {
            scanf("%d", &moves[i]);
        }

        int roulette[MAX_M];
        for (int i = 0; i < m; i++) {
            scanf("%d", &roulette[i]);
        }

        // dp[pos][step] = reachable? pos from 0 to n, step from 0 to m
        bool dp[MAX_N][MAX_M];
        memset(dp, false, sizeof(dp));
        dp[0][0] = true;

        for (int step = 0; step < m; step++) {
            for (int pos = 0; pos <= n; pos++) {
                if (!dp[pos][step]) continue;

                for (int r = 1; r <= k; r++) {
                    int next = pos + r;
                    if (next > n) next = n;

                    // apply move instruction at next position
                    int new_pos = next + moves[next];
                    if (new_pos < 0) new_pos = 0;
                    if (new_pos > n) new_pos = n;

                    dp[new_pos][step + 1] = true;
                }
            }
        }

        bool possible = false;
        for (int step = 0; step <= m; step++) {
            if (dp[n][step]) {
                possible = true;
                break;
            }
        }

        printf("%s\n", possible ? "OK" : "NG");
    }
    return 0;
}

#include <stdio.h>
