int main() {
    int N, M;
    while (scanf("%d %d", &N, &M) == 2 && (N || M)) {
        int instruction[10001];
        memset(instruction, 0, sizeof(instruction));

        // Read instructions until "0 0" or similar terminator
        // Actually need to know how many instructions there are
        // Let me assume we read until a line with "0 0"
        int pos, offset;
        while (scanf("%d %d", &pos, &offset) == 2 && (pos || offset)) {
            instruction[pos] = offset;
        }

        // BFS from position 0
        int visited[10001];
        memset(visited, 0, sizeof(visited));
        int queue[10001];
        int head = 0, tail = 0;

        // Apply instruction at start position 0 if any
        int start = 0;
        if (instruction[start] != 0) {
            start = start + instruction[start];
            if (start < 0) start = 0;
            if (start > N) start = N;
        }

        if (start == N) {
            printf("OK\n");
            continue;
        }

        visited[start] = 1;
        queue[tail++] = start;
        int found = 0;

        while (head < tail && !found) {
            int cur = queue[head++];
            for (int roll = 1; roll <= M; roll++) {
                int next = cur + roll;
                if (next >= N) {
                    found = 1;
                    break;
                }
                // Apply instruction
                if (instruction[next] != 0) {
                    next = next + instruction[next];
                    if (next < 0) next = 0;
                    if (next >= N) { found = 1; break; }
                }
                if (!visited[next]) {
                    visited[next] = 1;
                    queue[tail++] = next;
                }
            }
        }

        printf("%s\n", found ? "OK" : "NG");
    }
    return 0;
}

