int main(void) {
    int n, m, p;

    while (scanf("%d %d %d", &n, &m, &p) == 3) {
        if (n == 0 && m == 0 && p == 0) break;

        int *a = (int *)malloc((n + 1) * sizeof(int));
        for (int i = 0; i <= n; i++) a[i] = 0;

        for (int i = 0; i < p; i++) {
            int x, y;
            scanf("%d %d", &x, &y);
            a[x] = y;
        }

        int *q = (int *)malloc((n + 1) * sizeof(int));
        int *vis = (int *)malloc((n + 1) * sizeof(int));
        for (int i = 0; i <= n; i++) vis[i] = 0;

        int head = 0, tail = 0;
        q[tail++] = 0;
        vis[0] = 1;

        while (head < tail) {
            int cur = q[head++];

            for (int d = 1; d <= m; d++) {
                int nxt = cur + d;
                if (nxt > n) nxt = n;

                nxt += a[nxt];
                if (nxt < 0) nxt = 0;
                if (nxt > n) nxt = n;

                if (!vis[nxt]) {
                    vis[nxt] = 1;
                    q[tail++] = nxt;
                }
            }
        }

        if (vis[n]) printf("OK\n");
        else printf("NG\n");

        free(a);
        free(q);
        free(vis);
    }

    return 0;
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int n = Integer.parseInt(parts[0]);
            int m = Integer.parseInt(parts[1]);

            if (n == 0 && m == 0) break;

            // Read board commands: positions 0..n (0 is start, n is goal)
            int[] board = new int[n + 1];
            String[] cmdLine = br.readLine().trim().split(" ");
            for (int i = 0; i <= n; i++) {
                board[i] = Integer.parseInt(cmdLine[i]);
            }

            // Read roulette outcomes
            int[] roulette = new int[m];
            String[] rouletteLine = br.readLine().trim().split(" ");
            for (int i = 0; i < m; i++) {
                roulette[i] = Integer.parseInt(rouletteLine[i]);
            }

            // BFS/DP to check reachability
            boolean[] visited = new boolean[n + 1];
            Queue<Integer> queue = new LinkedList<>();
            queue.offer(0);
            visited[0] = true;

            int rouletteIndex = 0;
            boolean possible = false;

            while (!queue.isEmpty() && rouletteIndex < m) {
                int size = queue.size();
                Set<Integer> nextSet = new HashSet<>();

                for (int i = 0; i < size; i++) {
                    int pos = queue.poll();
                    int step = roulette[rouletteIndex];
                    int newPos = pos + step;

                    // Handle bounds: if past goal, set to goal
                    if (newPos > n) {
                        newPos = n;
                    }

                    // Apply board command if not at goal
                    if (newPos != n) {
                        newPos += board[newPos];
                        // Handle bounds again after command
                        if (newPos > n) {
                            newPos = n;
                        }
                        if (newPos < 0) {
                            newPos = 0;
                        }
                    }

                    if (newPos == n) {
                        possible = true;
                        break;
                    }

                    if (!visited[newPos]) {
                        nextSet.add(newPos);
                    }
                }

                if (possible) break;

                // Add all positions from nextSet to queue and mark visited
                for (int p : nextSet) {
                    visited[p] = true;
                    queue.offer(p);
                }

                rouletteIndex++;
            }

            // Also check if we can reach goal after using all roulette outcomes
            if (!possible) {
                // If queue is empty, no more positions to explore
                // If we have used all roulette outcomes and no position is at goal
                // then impossible
                // However, if we already reached goal during process, it's OK
            }

            System.out.println(possible ? "OK" : "NG");
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            int n = Integer.parseInt(first);
            int m = fs.nextInt();

            if (n == 0 && m == 0) break;

            int[] move = new int[n + 1]; // positions 0..n, n is goal
            for (int i = 1; i < n; i++) {
                move[i] = fs.nextInt();
            }
            move[0] = 0;
            move[n] = 0;

            boolean[] visited = new boolean[n + 1];
            ArrayDeque<Integer> q = new ArrayDeque<>();
            visited[0] = true;
            q.add(0);

            while (!q.isEmpty()) {
                int cur = q.poll();
                if (cur == n) break;

                for (int d = 1; d <= m; d++) {
                    int next = cur + d;
                    if (next > n) next = n;

                    int after = next + move[next];
                    if (after > n) after = n;
                    if (after < 0) after = 0;

                    if (!visited[after]) {
                        visited[after] = true;
                        q.add(after);
                    }
                }
            }

            out.append(visited[n] ? "OK" : "NG").append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            N = int(next(it))
            M = int(next(it))
        except StopIteration:
            break

        if N == 0 and M == 0:
            break

        move = [0] * (N + 1)
        for i in range(1, N):
            move[i] = int(next(it))
        move[N] = 0

        visited = [False] * (N + 1)
        q = deque([0])
        visited[0] = True

        while q:
            pos = q.popleft()
            if pos == N:
                break

            for d in range(1, M + 1):
                nxt = pos + d
                if nxt > N:
                    nxt = N

                nxt += move[nxt]
                if nxt < 0:
                    nxt = 0
                elif nxt > N:
                    nxt = N

                if not visited[nxt]:
                    visited[nxt] = True
                    q.append(nxt)

        out.append("OK" if visited[N] else "NG")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
